    _excl_instr_classes: Set[type] = set()
    _comment_class: Callable | None = None
    _auxiliary_libraries: Dict[tuple[int, str], Any] = {}

    # _comment_cls = CommentLine
    _assignment_class = AssignmentStatementLine
    _routinecall_class = RoutineCallContainer
    # _kernelcall_class = KernelCallContainer
    _extimport_class = ExternalImport
    _mfe_container_class = MultiFrameExpandContainer
    _multiframe_variable_class = LibRoutineMultiFrame

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        cls._supp_instr_handler = dict(getattr(cls, "_supp_instr_handler", {}))
        cls._excl_instr_classes = set(
            getattr(cls, "_excl_instr_classes", set())
        )
        cls._auxiliary_libraries = dict(
            getattr(cls, "_auxiliary_libraries", {})
        )
        cls.set_default_handlers()

    def __init__(
        self,
        name: str,
        makefile=None,
        extra_instr_handler=None,
        avoid_instr_classes=None,
        **params: Any,
    ):
        """
        Initialize a builder instance.

        :param name: Logical builder instance name used in logs.
        :param makefile: Optional makefile integration object.
        :param extra_instr_handler: Optional per-instance instruction-handler
            overrides.
        :param avoid_instr_classes: Optional per-instance set of forbidden
            instruction classes.
        :param params: Additional configuration parameters stored on the
            builder segment.
        """
        self._name = name
        self._makefile = makefile

        if extra_instr_handler is None:
            extra_instr_handler = {}
        if avoid_instr_classes is None:
            avoid_instr_classes = set()
        self._extra_instr_handler: Dict[type, Callable] = extra_instr_handler
        self._avoid_instr_classes: Set[type] = avoid_instr_classes

        super().__init__(**params)

