    @property
    def makefile(self):
        """Return the optional makefile integration object."""
        return self._makefile

    def checksum_payload(self):
        """Return a stable payload describing the builder configuration."""
        return {
            **super().checksum_payload(),
            "name": self._name,
            "extra_handlers": sorted(
                f"{cls.__module__}.{cls.__qualname__}"
                for cls in self._extra_instr_handler
            ),
            "avoid_classes": sorted(
                f"{cls.__module__}.{cls.__qualname__}"
                for cls in self._avoid_instr_classes
            ),
            "makefile": None
            if self._makefile is None
            else f"{type(self._makefile).__module__}.{type(self._makefile).__qualname__}",
        }

    def _detail_log_lines(self) -> Iterator[str]:
        """Yield builder-specific startup log lines."""
        yield f"Builder name: {self._name}"
        yield from BuilderSegment._detail_log_lines(self)
        supported = list(type(self)._supp_instr_handler.keys())
        if supported:
            yield f"supported ({len(supported)}):"
            for instruction_type in supported:
                yield f"  + {instruction_type.class_identifier()}"
        excluded = list(type(self)._excl_instr_classes)
        if excluded:
            yield f"excluded ({len(excluded)}):"
            for instruction_type in excluded:
                yield f"  - {instruction_type}"

        additional = list(self._extra_instr_handler.keys())
        if additional:
            yield f"additional ({len(additional)}):"
            for instruction_type in additional:
                yield f"  + {instruction_type.class_identifier()}"
        forbidden = list(self._avoid_instr_classes)
        if forbidden:
            yield f"forbidden ({len(forbidden)}):"
            for instruction_type in forbidden:
                yield f"  - {instruction_type}"

    def lookup_status(self, status: str) -> int:
        """
        Convert a textual routine-variable status to the internal bitmask.

        :param status: Status string such as ``IN``, ``OUT``, or ``INOUT``.
        :returns: Matching :class:`LibRoutineVariable` status flag.
        """
        if status.strip().upper() == "IN":
            return LibRoutineVariable.STATUS_INPUT
        if status.strip().upper() == "OUT":
            return LibRoutineVariable.STATUS_OUTPUT
        if status.strip().upper() == "INOUT":
            return LibRoutineVariable.STATUS_INOUT
        raise ValueError(f"unknown status: {status}")

    def handle_assignments(
        self,
        daa_assignments,
        lrv_assignments=None,
        contribute=None,
        context=None,
    ):
        """
        Convert ADAA and explicit routine-variable assignments into one mapping.

        :param daa_assignments: Instruction-variable to ADAA/status mapping.
        :param lrv_assignments: Optional explicit routine-variable assignments.
        :param contribute: Optional mapping to update in place.
        :param context: Build context providing the namespace for generated
            routine variables.
        :returns: Combined assignment mapping keyed by ``(instruction, key)``.
        """
        if contribute is None:
            contribute = {}

        if daa_assignments is not None:
            for instr_var, (adaa, status) in daa_assignments.items():
                if isinstance(status, str):
                    status = self.lookup_status(status)
                datatypes = tuple(adaa.datatypes())
                log.info(
                    f"Resolving ADAA assignments for {instr_var.get_name()}",
                    f"components: {len(datatypes)}",
                    f"status: {status}",
                    source=type(self).__name__,
                )
                for key, dtype in datatypes:
                    lrv = self.create_libroutine_variable(
                        name=f"{instr_var.get_name()}_{key}",
                        dtype=dtype,
                        size=adaa.get_fixed_size(),
                        status=status,
                        assignment=(instr_var, key),
                        namespace=context.namespace,
                        no_entry=True,
                    )
                    contribute[instr_var, key] = lrv
                    log.debug(
                        f"Registered routine variable {lrv.name}",
                        f"assignment: ({instr_var.get_name()}, {key})",
                        f"dtype={dtype}",
                        f"size={lrv.size}",
                        source=type(self).__name__,
                    )
        # if bff_assignments is not None:
        #     for instr_var, (adaa, status) in bff_assignments.items():
        #         if isinstance(status, str):
        #             status = self.lookup_status(status)
        #         for key, dtype in adaa.datatypes():
        #             lrv = self.create_libroutine_variable(
        #                 name=f"{instr_var.get_name()}_{key}",
        #                 dtype=dtype,
        #                 size=adaa.get_fixed_size(),
        #                 status=status,
        #                 assignment=(instr_var, key),
        #                 namespace=context.namespace,
        #                 no_entry=True,
        #             )
        #             contribute[instr_var, key] = lrv
        if lrv_assignments is not None:
            for (instr_var, key), lrv in lrv_assignments.items():
                contribute[instr_var, key] = lrv
        return contribute

    def create_libroutine_variable(
        self, *, name, dtype, status, size, namespace=None, **kwargs
    ):
        """
        Create a backend-specific routine variable.

        Subclasses must implement this to map status, dtype, and size to the
        concrete variable class used by the target backend.
        """
        raise NotImplementedError("must be implemented in subclass")

    def add_supported_instruction_class(
        self, instruction_class: type, handler: Callable
    ) -> None:
        """Register an additional per-instance instruction handler."""
        self._extra_instr_handler[instruction_class] = handler

    def add_forbidden_instruction_class(self, instruction_class: type) -> None:
        """Mark an instruction class as forbidden for this builder instance."""
        self._avoid_instr_classes.add(instruction_class)

    @classmethod
    @log.wrap_call
    def set_default_handler(cls, instruction_class: type, handler: Callable):
        """Register a default handler for an instruction class."""
        cls._supp_instr_handler[instruction_class] = handler
        if instruction_class in cls._excl_instr_classes:
            cls._excl_instr_classes.remove(instruction_class)

    @classmethod
    @log.wrap_call
    def set_default_forbidden(cls, instruction_class: type) -> None:
        """Mark an instruction class as unsupported by default."""
        cls._excl_instr_classes.add(instruction_class)
        if instruction_class in cls._supp_instr_handler:
            del cls._supp_instr_handler[instruction_class]

    @log.wrap_call
    def match_instruction(self, instruction: Instruction) -> Callable | None:
        """
        Resolve the handler function used to lower one instruction.

        :param instruction: Instruction to match against the supported handler
            tables.
        :returns: Matching handler callable, or ``None`` if unsupported.
        """
        for elder in instruction.__class__.__mro__:
            # note: mro contains type(self) and then all parents

            # # check local classes
            if elder in self._avoid_instr_classes:
                return None
            if elder in self._extra_instr_handler:
                return self._extra_instr_handler[elder]

            # check defaults
            if elder in type(self)._excl_instr_classes:
                return None
            if elder in type(self)._supp_instr_handler:
                return type(self)._supp_instr_handler[elder]
        return None

    @log.wrap_call
    def request_temp(
        self, container, name, generating, autorequire=True, **genargs
    ):
        """
        Request a temporary variable from the active namespace.

        :param container: Container requesting the temporary.
        :param name: Base name of the temporary variable.
        :param generating: Variable class or factory used to create it.
        :param autorequire: If ``True``, require the variable on the container
            immediately.
        :param genargs: Additional generator arguments passed to the namespace.
        :returns: Generated temporary variable.
        """
        variable = container.context.namespace.request_temp(
            generating, name, origin=container, **genargs
        )
        if autorequire:
            container.requires(variable)
        return variable

