    @log.wrap_call_gen
    def containers_from_instruction(
        self,
        instruction: Instruction,
        context,
        **buildargs: Any,
    ):
        """
        Lower one instruction into backend-specific code containers.

        :param instruction: Instruction to lower.
        :param context: Build context active at the current location.
        :param buildargs: Additional backend-specific build arguments.
        :returns: Generator yielding code containers.
        """

        handler = None

        handler = self.match_instruction(instruction)
        # match instruction returns a callable referred to as generating.
        # generating takes the instruction, the builder, a context object and
        # buildargs as arguments and yields all code containers that are built
        # from there. The code containers are filled already, so calling that
        # routine on the tree root will recursively trigger all children to be
        # built recursively.
        # As builder is passed as an argument and the context is updated upon
        # traversing the branches, the generating callables can call
        # containers_from_instruction on the children.

        # there has to be a match, otherwise the builder cannot build this.
        if handler is None:
            raise TypeError("Instruction class not supported")

        debug(f"\tTarget     : {instruction}")
        debug(f"\tBuilder    : {self}")
        debug(f"\tContext    : {context}")
        debug(f"\tEnvironment: {context.environment}")
        debug(f"\tLevel      : {context.level}")
        debug(f"\tContainer  : {context.container}")
        debug(f"\tParent Ctxt: {context.parent_context}")
        debug(f"\tParent Cont: {context.parent}")
        debug(f"\tNamespace  : {context.namespace}")
        debug(f"\tbuild args : {buildargs}")

        yield from handler(
            self,
            instruction=instruction,
            context=context,
            buildargs=buildargs,
        )
        # fill with content. This is not done on init automatically to be able
        # to implement that lazy as well.

    @log.wrap_call
    def instructions_to_routine_container(
        self,
        name,
        instructions,
        context,
        daa_assignments=None,
        lrv_assignments=None,
        container_class=None,
        **buildargs: Any,
    ):
        """
        Build a routine container from an instruction sequence.

        :param name: Routine name.
        :param instructions: Iterable of instructions forming the routine body.
        :param context: Parent build context.
        :param daa_assignments: Optional ADAA-backed variable assignments.
        :param lrv_assignments: Optional explicit routine-variable assignments.
        :param container_class: Concrete routine-container class to construct.
        :param buildargs: Additional backend-specific build arguments.
        :returns: Populated routine container.
        """
        if container_class is None:
            raise ValueError("No container class provided")

        routine_context = context.inherit()

        # for source, (adaa, state) in assignments.items():
        #     for key, datatype in adaa.datatypes():
        #         if state && 3 == 1:
        #             libroutinevar = Input
        #         routine_context.namespace.assign(source, key, assignment)

        all_assignments = self.handle_assignments(
            daa_assignments=daa_assignments,
            lrv_assignments=lrv_assignments,
            # bff_assignments=bff_assignments,
            context=context,
        )
        instruction_count = len(tuple(instructions))
        log.info(
            f"Creating routine container {name}",
            f"root instructions: {instruction_count}",
            f"resolved assignments: {len(all_assignments)}",
            f"container class: {container_class.__module__}.{container_class.__qualname__}",
            source=type(self).__name__,
        )

        for (source, key), assignment in all_assignments.items():
            routine_context.namespace.assign(source, key, assignment)
            log.debug(
                f"Namespace assignment registered for {source.get_name()}[{key}]",
                f"-> {assignment.name}",
                source=type(self).__name__,
            )

        routine_container = container_class(
            name,
            context=routine_context,
            **buildargs,
        )

        for instruction in instructions:
            for container in self.containers_from_instruction(
                instruction,
                context=routine_container.context,
                **buildargs,
            ):
                routine_container.append(container)
        log.info(
            f"Finished lowering routine container {name}",
            source=type(self).__name__,
        )
        return routine_container

